def check(pw):
    fails = []
    if len(pw) < 12: fails.append('too short')
    if not any(c.isupper() for c in pw): fails.append('no uppercase')
    if not any(c.isdigit() for c in pw): fails.append('no digit')
    if not any(not c.isalnum() for c in pw): fails.append('no symbol')
    return fails or ['OK']
for pw in ['Sunset!2026ok', 'short!1A', 'NoDigits!Here', 'alllowercase1!', 'Valid#Pass99']:
    print(pw, '->', check(pw))

